'use strict';
(() => {
  const D=window.BANGLADESH, $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
  const PREFIX='bangladesh-social-dialogue-2026-v1-';
  const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const main=$('#main');
  function read(k,fallback){try{return JSON.parse(localStorage.getItem(PREFIX+k))??fallback;}catch{return fallback;}}
  function write(k,value){try{localStorage.setItem(PREFIX+k,JSON.stringify(value));return true;}catch{toast('This browser could not save. Export your work before leaving.');return false;}}
  let selected=read('workshop','institutions'), completed=read('completed',[]), notes=read('notes',{}), board=read('board',[]);
  if(!D.workshops.some(w=>w.id===selected))selected='institutions';
  if(!Array.isArray(completed))completed=[];
  if(!notes||typeof notes!=='object'||Array.isArray(notes))notes={};
  if(!Array.isArray(board))board=[];
  let route='home',params=new URLSearchParams(),unlocked=null,key=null,authTime=0,loadingFile=false;
  const timer={remaining:300,deadline:0,running:false,full:false};
  let filterQuery='';
  function toast(message){const el=$('#toast');el.textContent=message;el.classList.add('show');clearTimeout(el._timer);el._timer=setTimeout(()=>el.classList.remove('show'),4500);}
  function go(page,extra={}){const q=new URLSearchParams(extra);location.hash=page+(q.size?'?'+q:'');}
  const link=(page,label,cls='button',extra={})=>`<a class="${cls}" href="#${page}${Object.keys(extra).length?'?'+new URLSearchParams(extra):''}">${label}</a>`;
  const dl=(file,label='Download',cls='button small secondary')=>`<a class="${cls}" href="${esc(file)}" download>${label} <span aria-hidden="true">↓</span></a>`;
  const header=(eyebrow,title,description)=>`<div class="page-head"><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${description}</p></div>`;
  const current=()=>D.workshops.find(w=>w.id===selected);
  const sessions=w=>w.days.flatMap(d=>d.items.filter(s=>s.session).map(s=>({...s,day:d})));
  function switcher(page,extra={}){return `<div class="workshop-switch" aria-label="Choose a workshop">${D.workshops.map((w,i)=>`<a href="#${page}?${new URLSearchParams({w:w.id,...extra})}" aria-current="${selected===w.id}">${String(i+1).padStart(2,'0')} · ${w.short}</a>`).join('')}</div>`;}
  function dateLabel(iso,short=false){return new Intl.DateTimeFormat('en-GB',{day:'numeric',month:'short',...(short?{}:{weekday:'short'}),timeZone:'Asia/Dhaka'}).format(new Date(iso+'T06:00:00+06:00'));}
  function ordinal(w){return w.id==='institutions'?'01':'02';}
  function numberParam(name,max,fallback){const n=Number(params.get(name));return Number.isInteger(n)&&n>=1&&n<=max?n:fallback;}
  function render(){
    const raw=(location.hash.slice(1)||'home').split('?');route=raw[0];params=new URLSearchParams(raw.slice(1).join('?'));
    if(D.workshops.some(w=>w.id===params.get('w'))){selected=params.get('w');write('workshop',selected);}
    const routes={home,programme,activities,games,resources,notebook,facilitator};
    if(!routes[route])route='home';
    if(authTime&&Date.now()-authTime>90*60*1000){key=null;unlocked=null;authTime=0;}
    filterQuery='';main.innerHTML=routes[route]();
    $$('nav a').forEach(a=>{const active=a.dataset.route===route||route==='programme'&&a.dataset.workshop===selected;a.classList.toggle('active',active);if(active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});
    document.title=({home:'Welcome',programme:current().short,activities:'Activity desk',games:'Call It What It Is',resources:'Reference library',notebook:'My notebook & plans',facilitator:'Facilitator view'}[route])+' · Bangladesh 2026';
    timer.full=false;paintTimer();
  }
  function home(){return `
    <section class="hero"><div class="hero-copy"><div class="eyebrow">Dhaka, Bangladesh · 26 October–1 November 2026</div><h1>Stronger institutions.<br>Dialogue that delivers.</h1><p>A shared learning space for two workshops on tripartite institutions and the secretariats that make them work.</p><div class="actions">${link('programme','Explore workshop 01 →','button',{w:'institutions'})}${link('programme','Explore workshop 02 →','button secondary',{w:'secretariats'})}</div><div class="hero-tags"><span>Face-to-face learning</span><span>Practical tools</span><span>Institutional action</span></div></div><aside class="hero-art" aria-label="Government, employers and workers: from dialogue to delivery"><div class="eyebrow">Three voices. Shared purpose.</div><div class="big-type">From dialogue<br>to delivery.</div><div class="constituents"><span>Government</span><span>Employers</span><span>Workers</span></div><p>Design policy together.<br>Build the capacity to put it into practice.</p></aside></section>
    <div class="section-title"><h2>Choose your workshop</h2><small>Separate programmes · shared tools</small></div>
    <div class="grid two">${D.workshops.map(w=>`<article class="card workshop-card"><div class="card-top"><span class="badge">Workshop ${ordinal(w)} · ${w.code}</span><span class="workshop-number" aria-hidden="true">${ordinal(w)}</span></div><div class="workshop-date">${w.dates} · ${w.duration} days</div><h2>${w.id==='institutions'?'Strengthening Tripartite Social Dialogue Institutions<span>From Policy Design to Effective Implementation and Institutional Transformation</span>':'Strengthening the Capacities of the Secretariats<span>of Tripartite Social Dialogue Institutions in Bangladesh</span>'}</h2><p>${esc(w.participants)}.</p><div class="card-rule"><small>Your practical output</small><p>${w.id==='institutions'?'Draft policy proposals and institutional action plans with clear responsibilities, timelines and monitoring.':'An individual 30-day improvement plan, a three-month institutional roadmap and draft operating protocols.'}</p></div><div class="actions">${link('programme','Open programme →','button',{w:w.id})}${dl(w.agenda,'Rev.1 agenda','button small secondary')}</div></article>`).join('')}</div>
    <div class="stats"><div><strong>2</strong><span>connected workshops</span></div><div><strong>24</strong><span>working sessions</span></div><div><strong>20</strong><span>participant handouts</span></div><div><strong>12</strong><span>game scenarios</span></div></div>
    <div class="section-title"><h2>Make the learning yours</h2></div>
    <div class="grid three"><article class="card"><span class="shortcut-number">01 / PREPARE</span><h3>The activity desk</h3><p>Find each session’s worksheets, case notes and reusable templates. Preview a handout or download an editable copy.</p>${link('activities','Find your activity →','text-link',{w:selected})}</article><article class="card highlight"><span class="shortcut-number" style="color:white">02 / PLAY & DISCUSS</span><h3>Call It What It Is</h3><p>The social dialogue game from Kenya. Identify the form, the setting and one change that would improve the process.</p>${link('games','Open the game desk →','text-link')}</article><article class="card"><span class="shortcut-number">03 / PUT IT TO WORK</span><h3>Your notebook & plans</h3><p>Keep reflections and turn them into an institutional action plan or practical secretariat improvements.</p>${link('notebook','Start your notebook →','text-link',{w:selected})}</article></div>
    <div class="callout"><strong>Before you arrive:</strong> download your workshop’s Rev.1 agenda and handout pack. Workshop 01 ends at 12:30 on 29 October; Workshop 02 ends at 12:30 on 1 November. Venue: Dhaka, exact venue to be confirmed.</div>
    <div class="grid two"><article class="card"><span class="badge">Shared reference</span><h3>Bangladesh’s dialogue architecture</h3><p>Use the supplied NSDF notification and the ILO’s reference materials to examine mandates, coordination, inclusion and follow-up.</p>${link('resources','Explore the reference library →','text-link')}</article><article class="card"><span class="badge badge-outline">For facilitators</span><h3>Everything for the room</h3><p>Unlock session slide decks, trainer scripts, a discussion timer and a game results board.</p>${link('facilitator','Open facilitator view →','text-link')}</article></div>`;}

  function programme(){
    const w=current(),dn=numberParam('day',w.days.length,1),day=w.days[dn-1],ss=day.items.filter(s=>s.session),done=ss.filter(s=>completed.includes(s.id)).length;
    return switcher('programme')+header(`Workshop ${ordinal(w)} · ${w.code} · Programme Rev.1`,esc(w.short),esc(w.title))+`
      <section class="programme-summary"><div><span class="badge">${w.dates} · ${w.duration} days</span><p style="margin-top:14px">${esc(w.outputs)}.</p></div><div class="actions">${dl(w.agenda,'Download Rev.1 agenda','button small secondary')}<button class="button small secondary" data-calendar>Add sessions to calendar ↓</button></div></section>
      <div class="tabs" aria-label="Workshop days">${w.days.map(d=>link('programme',`Day ${d.number} · ${dateLabel(d.date,true)}`,'',{w:w.id,day:d.number}).replace('<a ','<a aria-current="'+(d.number===dn)+'" ')).join('')}</div>
      <div class="day-head"><div><div class="eyebrow">Day ${day.number} · ${dateLabel(day.date)} 2026 ${day.number===w.days.length?'· Half day':''}</div><h2>${esc(day.theme)}</h2></div><div class="progress-wrap"><small>${done} of ${ss.length} sessions marked complete</small><div class="progress"><span style="width:${100*done/ss.length}%"></span></div></div></div>
      <div class="schedule">${day.items.map(s=>!s.session?`<div class="session agenda-break"><div class="session-time">${esc(s.time)}</div><div><p>${esc(s.title)}</p></div></div>`:`<article class="session ${completed.includes(s.id)?'complete':''}"><div class="session-time">${esc(s.time)}<small>Session ${s.session}</small></div><div><h3>${esc(s.title)}</h3><details><summary>Session themes & activities</summary><ul>${s.topics.map(t=>`<li>${esc(t)}</li>`).join('')}</ul></details><div class="actions">${link('activities',s.handouts.length?'Open session activities →':'Open activity desk →','text-link',{w:w.id,session:s.session})}${s.session===1?link('games','Play Call It What It Is','button small secondary'):''}</div></div><input type="checkbox" data-complete="${s.id}" aria-label="Mark session ${s.session} complete" ${completed.includes(s.id)?'checked':''}></article>`).join('')}</div>
      <p class="source-note">Programme reproduced from the supplied Rev.1 draft agenda. All times are Dhaka time (UTC+6). Exact venue and session leads are to be confirmed. Session checkmarks are saved on this device.</p>`;
  }
  function resourceCards(w,session=0,query=''){
    const rows=D.activities.filter(a=>a.workshop===w.id&&(!session||a.sessions.includes(session))&&(!query||(`${a.title} ${a.number}`).toLowerCase().includes(query.toLowerCase())));
    if(!rows.length)return `<div class="empty"><h3>No handouts match these filters</h3><p>Choose another session or clear the search.</p><button class="button secondary" data-clear-filters>Show all handouts</button></div>`;
    return `<div class="grid two">${rows.map(a=>`<article class="card resource-card"><span class="resource-tag">${w.code} · ${a.sessions.length>1?'Reusable toolkit · Sessions '+a.sessions.join(', '):'Session '+a.sessions[0]}</span><h3>${esc(a.title)}</h3><p>${a.sessions.length>1?'Seven reusable templates, including the dispatch log, chair briefing, action sheet, register of conclusions and improvement plans.':'Participant handout · editable Word document'}</p><div class="actions"><button class="button small" data-preview="${a.id}">Preview handout</button>${dl(a.file,'Download Word')}</div></article>`).join('')}</div><p class="source-note">${rows.length} handout${rows.length===1?'':'s'} shown. Training scenarios, figures and mock records in exercise materials are illustrative. Use the original Word document for printing and completing tables.</p>`;
  }
  function activities(){
    const w=current(),session=numberParam('session',sessions(w).length,0);
    return switcher('activities')+header(`Workshop ${ordinal(w)} · Participant downloads`,'The activity desk','Choose a session. Open its worksheet in the dashboard or download the editable Word version.')+`
      <div class="filters"><label class="field">Session<select id="activity-session"><option value="0">All sessions</option>${sessions(w).map(s=>`<option value="${s.session}" ${s.session===session?'selected':''}>${s.session} · ${esc(s.title)}</option>`).join('')}</select></label><label class="field">Find a handout<input id="activity-search" type="search" placeholder="e.g. evidence, minutes, action plan" maxlength="100"></label>${dl(w.pack,'All handouts + Rev.1 agenda','button small secondary')}</div>
      ${session&&w.id==='secretariats'&&session>=6?'<div class="callout"><strong>The supplied reusable toolkit supports Modules 6–11.</strong> It includes the seven secretariat templates. Separate activity sheets mentioned in the trainer scripts for these modules were not included in the supplied materials.</div>':''}
      <div id="activity-results" aria-live="polite">${resourceCards(w,session)}</div>`;
  }
  function games(){return header('Shared workshop game · From the Kenya dashboard','Call It What It Is','Twelve fictional situations. Look past the label and examine what the parties actually do.')+`
    <section class="game-cover"><div><span class="badge" style="background:#ffffff20;color:white">Play together · One device per team</span><h2>They called it consultation.<br>Was it?</h2><p>Name the form of dialogue, identify the setting and suggest one useful change. Compare your reasoning with the game’s feedback.</p><div class="actions"><a class="button light" href="games/dialogue/index.html">Start the game →</a>${link('facilitator','Facilitator tools','button light')}</div></div><div class="game-facts"><div><strong>12</strong><span>fictional scenarios</span></div><div><strong>240</strong><span>possible learning points</span></div><div><strong>~22 min</strong><span>including the debrief</span></div></div></section>
    <div class="section-title"><h2>How to play</h2></div><div class="grid two"><article class="card"><h3>At the table</h3><ol class="steps"><li>Choose a team alias and use one shared device, or select individual practice.</li><li>Read each scenario. Choose the form and the bipartite, tripartite or neither setting.</li><li>Write one useful change, then lock in your answer to see the explanation.</li><li>At the end, share the six-character result code with the facilitator.</li></ol></article><article class="card"><h3>What counts</h3><p>10 points for the form, 5 for the setting and up to 5 for a change recognized by the game’s keyword guide. Two arguable cases allow alternative classifications.</p><p>Rank teams by learning points, then by elapsed time for a tie. The suggested change is a discussion prompt; keyword recognition does not assess the quality of the full answer.</p><div class="callout" style="margin-bottom:0"><strong>Good information-sharing matters.</strong> A more intensive form is not automatically more appropriate. Discuss what the situation requires.</div></article></div>
    <p class="source-note">This is the original Kenya game, duplicated for these Bangladesh workshops. Its fictional public-health, higher-education and national scenarios, feedback and scoring are preserved. Practice saves on the team’s device. A live race uses the same external service as the Kenya dashboard; its separate sign-in remains in place.</p>`;}

  const REFERENCES=[
    {tag:'ILO guide · 2013',title:'National Tripartite Social Dialogue',text:'Practical guidance on establishing and strengthening national tripartite social dialogue mechanisms.',url:'https://www.ilo.org/publications/national-tripartite-social-dialogue-ilo-guide-improved-governance'},
    {tag:'International labour standard',title:'Convention No. 87',text:'Freedom of Association and Protection of the Right to Organise Convention, 1948.',url:'https://normlex.ilo.org/dyn/nrmlx_en/f?p=NORMLEXPUB%3A12100%3A0%3A%3ANO%3A%3AP12100_INSTRUMENT_ID%2CP12100_LANG_CODE%3A312232%2Cen'},
    {tag:'International labour standard',title:'Convention No. 98',text:'Right to Organise and Collective Bargaining Convention, 1949.',url:'https://normlex.ilo.org/dyn/nrmlx_en/f?p=NORMLEXPUB%3A12100%3A0%3A%3ANO%3A%3AP12100_INSTRUMENT_ID%2CP12100_LANG_CODE%3A312243%2Cen'},
    {tag:'International labour standard',title:'Convention No. 144',text:'Tripartite Consultation (International Labour Standards) Convention, 1976. Its consultation requirements concern international labour standards.',url:'https://normlex.ilo.org/dyn/nrmlx_en/f?p=NORMLEXPUB%3A12100%3A0%3A%3ANO%3A%3AP12100_INSTRUMENT_ID%2CP12100_LANG_CODE%3A312289%2Cen'},
    {tag:'International labour standard',title:'Recommendation No. 204',text:'Transition from the Informal to the Formal Economy Recommendation, 2015.',url:'https://www.ilo.org/resource/other/ilc/ilc104/r204-recommendation-concerning-transition-informal-formal-economy'},
    {tag:'ILO knowledge hub',title:'Social dialogue and tripartism',text:'ILO resources on dialogue institutions, participation and labour governance.',url:'https://www.ilo.org/topics-and-sectors/social-dialogue-and-tripartism'}
  ];
  function resources(){return header('Read · Compare · Apply','The reference library','A focused desk for the two workshops: Bangladesh’s institutional context, relevant standards and practical ILO guidance.')+`
    <section class="card" style="border-top:5px solid var(--cyan)"><span class="badge">Bangladesh · Supplied reference</span><h2 style="margin-top:18px">The National Social Dialogue Forum</h2><p>The supplied English translation of the notification dated 10 August 2026, published in the Bangladesh Gazette on 13 August 2026. Use it to examine the Forum’s mandate, coordination with the NTCC and other tripartite bodies, and the arrangements for follow-up.</p><div class="actions"><a class="button" href="downloads/NSDF_Unofficial_English_Translation.pdf" target="_blank" rel="noopener">Read the notification ↗</a>${dl('downloads/NSDF_Unofficial_English_Translation.pdf','Download PDF')}</div><p class="source-note">Unofficial English translation supplied for the workshops. Consult the authoritative Gazette text when interpreting legal requirements.</p></section>
    <div class="section-title"><h2>International standards & practice</h2></div><div class="grid two">${REFERENCES.map(r=>`<article class="card resource-card"><span class="resource-tag">${r.tag}</span><h3>${r.title}</h3><p>${r.text}</p><div class="actions">${r.file?dl(r.file,'Download full text'):''}${r.url?`<a class="button small secondary" href="${esc(r.url)}" target="_blank" rel="noopener">Open ILO source ↗</a>`:''}</div></article>`).join('')}</div>
    <div class="callout"><strong>Bring a reference back to your institution:</strong> What does your mandate allow? Who must be represented? What happens to a recommendation after the meeting? Use your workshop’s worksheets to record the answers.</div><p class="source-note">The Convention links above lead to official ILO texts. No country ratification status is asserted here.</p>`;}

  const COMMON_FIELDS=[['institution','My institution / team','text'],['learning','What I want to take away','textarea'],['reflection','My session reflections','textarea'],['questions','Questions to explore with the group','textarea']];
  const INSTITUTION_FIELDS=[['issue','Priority policy or institutional issue','textarea'],['evidence','Evidence and assumptions to check','textarea'],['objective','Objective and expected result','textarea'],['mandate','Legal or institutional mandate to check','textarea'],['responsibility','Responsible institution, lead and partners','textarea'],['timeline','Milestones and timeline','textarea'],['coordination','Coordination, referral and reporting arrangements','textarea'],['inclusion','Gender, inclusion and representation measures','textarea'],['resources','Resources and main implementation risks','textarea'],['indicators','Indicators and evidence of delivery','textarea']];
  const SECRETARIAT_FIELDS=[['priority1','30-day improvement 1 · Protocol or documentation','textarea'],['priority2','30-day improvement 2 · Technical support','textarea'],['priority3','30-day improvement 3 · Follow-up','textarea'],['month1','Month 1 · Foundation and accountability','textarea'],['month2','Month 2 · Technical excellence and neutrality','textarea'],['month3','Month 3 · Sustainability and planning','textarea'],['ownership','Leads, deadlines and evidence of success','textarea'],['rally','Our team’s rallying statement','textarea']];
  function noteField([id,label,type]){const value=notes[selected]?.[id]||'';return `<label class="field">${label}${type==='textarea'?`<textarea data-note="${id}" maxlength="30000" rows="4">${esc(value)}</textarea>`:`<input data-note="${id}" maxlength="300" value="${esc(value)}">`}</label>`;}
  function notebook(){const w=current();return switcher('notebook')+header(`Workshop ${ordinal(w)} · Reflect & take action`,'My notebook & plans','Keep your learning together and build the practical output for your workshop. Your two notebooks are saved separately on this device.')+`
    <div class="actions" style="margin-bottom:20px;margin-top:0"><button class="button" data-export-notes>Export readable notes ↓</button><button class="button secondary" data-backup-notes>Back up both notebooks ↓</button><label class="button secondary" for="restore-notes">Restore a backup<input id="restore-notes" type="file" accept="application/json,.json" hidden></label></div><p class="note-hint">Notes save automatically in this browser. They are not sent to the facilitator. Export a copy before changing devices or clearing browser data.</p>
    <div class="notebook-grid"><section class="card"><h2>My learning notebook</h2><div class="form-grid">${COMMON_FIELDS.map(noteField).join('')}</div></section><section class="card"><span class="badge">Your workshop output</span><h2 style="margin-top:18px">${w.id==='institutions'?'Policy proposal & institutional action plan':'My 30-day plan & three-month roadmap'}</h2><p class="muted">${w.id==='institutions'?'Use this working space alongside the proposal, implementation and peer-review handouts.':'Make three improvements within your own authority. For each, name the action, deadline and evidence of completion. Then agree a team deliverable for each month.'}</p><div class="form-grid">${(w.id==='institutions'?INSTITUTION_FIELDS:SECRETARIAT_FIELDS).map(noteField).join('')}</div></section></div><div class="actions"><button class="button" data-export-notes>Export this notebook ↓</button><button class="button secondary" data-print>Print this page</button><button class="button danger" data-clear-notes>Clear this workshop’s notebook</button></div><p id="save-state" class="save-state" role="status">Saved notes stay on this device.</p>`;}

  function facilitator(){
    if(!unlocked)return header('Facilitator access','Ready for the room','Unlock your session materials and workshop tools.')+`
      <section class="card login-card"><div class="lock-icon" aria-hidden="true">⌑</div><h2>Facilitator sign-in</h2><p class="muted">Use the workshop facilitator credentials.</p><form id="facilitator-login"><label class="field">Username<input name="username" id="facilitator-username" type="email" autocomplete="username" required></label><label class="field">Password<input name="password" id="facilitator-password" type="password" autocomplete="current-password" required></label><div class="actions"><button class="button" type="submit">Unlock facilitator view →</button></div><p id="login-error" class="error" role="alert"></p></form><p class="source-note">The first unlock needs an internet connection. Refreshing the page or signing out locks the materials again.</p></section>`;
    const tab=['materials','tools'].includes(params.get('tab'))?params.get('tab'):'materials',w=current();
    return header('Facilitator workspace','Your session desk','Programmes, teaching materials and practical controls for the two workshops.')+`
      <div class="facilitator-bar"><div><strong>Facilitator view unlocked</strong><small>Materials stay unlocked in this tab for up to 90 minutes.</small></div><button class="button small secondary" data-lock>Sign out & lock</button></div>
      <div class="tabs" aria-label="Facilitator tools"><a href="#facilitator?tab=materials&w=${selected}" aria-current="${tab==='materials'}">Session materials</a><a href="#facilitator?tab=tools&w=${selected}" aria-current="${tab==='tools'}">Timer & game board</a></div>
      ${tab==='materials'?switcher('facilitator',{tab:'materials'})+`<section class="programme-summary"><div><span class="badge">${w.code} · ${w.dates}</span><h2 style="margin-top:14px">${esc(w.title)}</h2><p>Original slide decks include speaker notes. Trainer scripts are keyed to the slide numbers.</p></div><div class="actions">${dl(w.agenda,'Rev.1 agenda','button small secondary')}${dl(w.pack,'Participant handouts','button small secondary')}</div></section>`+sessions(w).map(s=>{const slide=unlocked.find(r=>r.id===s.id&&r.kind==='slides'),script=unlocked.find(r=>r.id===s.id&&r.kind==='script');return `<article class="trainer-row"><span class="trainer-session">SESSION ${s.session}</span><div><h3>${esc(s.title)}</h3><p>${dateLabel(s.day.date)} · ${esc(s.time)} · ${slide?.slides||''} slides</p></div><div class="actions"><button class="button small" data-unlock-file="${slide?.file}">Slides ↓</button><button class="button small secondary" data-script="${script?.file}">Read script</button><button class="button small secondary" data-unlock-file="${script?.file}">Script ↓</button></div></article>`;}).join(''):toolsView()}`;
  }
  function clock(seconds){const n=Math.max(0,Math.ceil(seconds));return String(Math.floor(n/60)).padStart(2,'0')+':'+String(n%60).padStart(2,'0');}
  function timeLeft(){return timer.running?Math.max(0,(timer.deadline-Date.now())/1000):timer.remaining;}
  function toolsView(){return `<div class="grid two"><section class="card timer-card"><span class="badge">Discussion timer</span><h2 style="margin-top:17px">Make room for the conversation</h2><div class="timer-display" data-timer-display role="timer" aria-label="Time remaining">${clock(timeLeft())}</div><label class="field" style="max-width:180px;margin:auto">Set minutes<input id="timer-minutes" type="number" min="1" max="90" step="1" value="${Math.max(1,Math.round(timer.remaining/60))}"></label><div class="actions"><button class="button" data-timer="toggle">${timer.running?'Pause':'Start'}</button><button class="button secondary" data-timer="add">+30 seconds</button><button class="button secondary" data-timer="reset">Reset</button><button class="button secondary" data-timer="full">Project timer</button></div><p class="source-note" data-timer-caption>${timeLeft()===0?'Time is up. Continue when the group is ready.':'The timer is a discussion prompt. It never blocks the game.'}</p></section><section class="card"><span class="badge">Running Call It What It Is</span><h2 style="margin-top:17px">A simple room setup</h2><ol class="steps"><li>Ask each team to open the game and use one shared device.</li><li>Leave the session code blank for independent practice.</li><li>At the end, enter each team’s six-character result code below.</li><li>Discuss difficult classifications before announcing the ranking.</li></ol><div class="actions"><a class="button small" href="games/dialogue/index.html" target="_blank" rel="noopener">Open participant game ↗</a></div></section></div>
      <section class="card" style="margin-top:22px"><span class="badge">Result-code board · This device</span><h2 style="margin-top:17px">Learning points first. Time breaks a tie.</h2><p>Enter a team alias and the result code displayed at the end of the game. Each workshop has its own board.</p>${switcher('facilitator',{tab:'tools'})}<form id="result-form" class="code-form"><label class="field">Team alias<input id="result-team" maxlength="40" required placeholder="e.g. Table 1"></label><label class="field">Result code<input id="result-code" maxlength="6" minlength="6" required placeholder="Six characters" style="text-transform:uppercase" autocomplete="off"></label><button class="button" type="submit">Add result</button></form><p class="error" id="result-error" role="alert"></p><div id="board-results">${boardTable()}</div><div class="actions"><button class="button small secondary" data-export-board>Export results ↓</button><button class="button small danger" data-clear-board>Clear this workshop’s board</button></div></section>
      <div class="callout"><strong>Using the Kenya live race service:</strong> the copied game can also join sessions from the existing Kenya service. <a href="https://platform-grievance-india.darrin-dookie.chatgpt.site/games/facilitator" target="_blank" rel="noopener">Open the existing secure live board ↗</a> and create a separate session for this workshop. That service uses its own sign-in. The result-code board above needs no external service and does not synchronize between devices.</div>`;}
  function boardTable(){const rows=board.filter(r=>r.workshop===selected).sort((a,b)=>b.score-a.score||a.seconds-b.seconds);return rows.length?`<div class="table-scroll"><table class="leaderboard"><caption>Result codes record learning points and time rounded to five seconds. They are intended for classroom comparison.</caption><thead><tr><th scope="col">Rank</th><th scope="col">Team</th><th scope="col">Points</th><th scope="col">Time</th><th scope="col">Edit</th></tr></thead><tbody>${rows.map((r,i)=>`<tr><td>${i+1}</td><td>${esc(r.team)}</td><td><strong>${r.score}</strong> / 240</td><td>${clock(r.seconds)}</td><td><button class="button small secondary" data-remove-result="${esc(r.id)}" aria-label="Remove result for ${esc(r.team)}">Remove</button></td></tr>`).join('')}</tbody></table></div>`:'<p class="muted">No results entered for this workshop yet.</p>';}

  async function getBytes(path){const res=await fetch(path,{cache:'no-store'});if(!res.ok)throw new Error('A workshop file could not be loaded. Check your connection and try again.');return new Uint8Array(await res.arrayBuffer());}
  const partCaches=new WeakMap(),recipeCaches=new WeakMap();
  async function decrypt(path,cryptoKey){
    let data;
    if(/^protected\/A\d+_S\d+_.*\.(pptx|docx)\.enc$/.test(path)){
      let catalogue=recipeCaches.get(cryptoKey);
      if(!catalogue){catalogue=decrypt('protected/recipes.enc',cryptoKey).then(bytes=>JSON.parse(new TextDecoder().decode(bytes)));recipeCaches.set(cryptoKey,catalogue);}
      const encoded=(await catalogue)[path];
      if(typeof encoded!=='string')throw new Error('The requested teaching file is missing from the package.');
      data=Uint8Array.from(atob(encoded),c=>c.charCodeAt(0));
    }else data=await getBytes(path);
    if(new TextDecoder().decode(data.slice(0,4))!=='BD26')throw new Error('The workshop file has an unexpected format.');
    const plain=await crypto.subtle.decrypt({name:'AES-GCM',iv:data.slice(4,16)},cryptoKey,data.slice(16));
    if(new TextDecoder().decode(new Uint8Array(plain,0,Math.min(7,plain.byteLength)))!=='BDREC1\n')return plain;
    const recipe=JSON.parse(new TextDecoder().decode(new Uint8Array(plain,7)));
    if(!Number.isInteger(recipe.size)||recipe.size<0||recipe.size>30000000||!Array.isArray(recipe.parts))throw new Error('Invalid teaching-file package.');
    let cache=partCaches.get(cryptoKey);if(!cache){cache=new Map();partCaches.set(cryptoKey,cache);}
    const result=new Uint8Array(recipe.size);let position=0;
    for(const [name,offset,length] of recipe.parts){
      if(!/^p\d{4}\.enc$/.test(name)||!Number.isInteger(offset)||!Number.isInteger(length)||offset<0||length<0)throw new Error('Invalid teaching-file part.');
      if(!cache.has(name)){const pending=decrypt('protected/parts/'+name,cryptoKey).catch(error=>{cache.delete(name);throw error;});cache.set(name,pending);}
      const part=new Uint8Array(await cache.get(name));
      if(offset+length>part.length||position+length>result.length)throw new Error('Incomplete teaching-file package.');
      result.set(part.subarray(offset,offset+length),position);position+=length;
    }
    if(position!==result.length)throw new Error('Incomplete teaching-file package.');
    return result.buffer;
  }
  async function unlock(event){event.preventDefault();const form=event.target,button=form.querySelector('button'),error=$('#login-error');error.textContent='';button.disabled=true;button.textContent='Unlocking…';try{
    if(!window.crypto?.subtle)throw new Error('Open the dashboard through its HTTPS website to unlock the materials.');
    const username=form.elements.username.value.trim().toLowerCase(),password=form.elements.password.value;
    const meta=JSON.parse(new TextDecoder().decode(await getBytes('protected/kdf.json'))),salt=Uint8Array.from(atob(meta.salt),c=>c.charCodeAt(0));
    const material=await crypto.subtle.importKey('raw',new TextEncoder().encode(username+'\0'+password),'PBKDF2',false,['deriveKey']);
    const candidate=await crypto.subtle.deriveKey({name:'PBKDF2',salt,iterations:meta.iterations,hash:meta.hash},material,{name:'AES-GCM',length:256},false,['decrypt']);
    const manifest=await decrypt('protected/manifest.enc',candidate);unlocked=JSON.parse(new TextDecoder().decode(manifest));key=candidate;authTime=Date.now();form.elements.password.value='';render();toast('Facilitator view unlocked.');
  }catch(e){error.textContent=e.name==='OperationError'?'The username or password was not recognized. Check both and try again.':e.message;button.disabled=false;button.textContent='Unlock facilitator view →';}}
  function downloadBytes(filename,bytes,type='application/octet-stream'){const blob=bytes instanceof Blob?bytes:new Blob([bytes],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),30000);}
  async function protectedDownload(path,button){if(!unlocked||!key){go('facilitator');return;}if(loadingFile){toast('Please wait for the current download.');return;}const row=unlocked.find(r=>r.file===path);if(!row)return;loadingFile=true;const original=button.textContent;button.disabled=true;button.textContent='Preparing…';try{downloadBytes(row.name,await decrypt(row.file,key),row.kind==='slides'?'application/vnd.openxmlformats-officedocument.presentationml.presentation':'application/vnd.openxmlformats-officedocument.wordprocessingml.document');toast('Your download is ready.');}catch(e){toast(e.message||'Could not unlock this file. Try again.');}finally{loadingFile=false;button.disabled=false;button.textContent=original;}}
  function previewDocument(title,html,action=''){$('#document-title').textContent=title;$('#document-body').innerHTML=action+html;$('#document-viewer').showModal();}
  function exportNotebook(){const w=current(),ns=notes[selected]||{},fields=[...COMMON_FIELDS,...(selected==='institutions'?INSTITUTION_FIELDS:SECRETARIAT_FIELDS)];let text=`# ${w.title}\n${w.code} · ${w.dates}\n\n`;for(const [id,label] of fields)text+=`## ${label}\n${ns[id]||'—'}\n\n`;downloadBytes(w.code+'_My_Notebook.md',text,'text/markdown;charset=utf-8');}
  function calendar(){const w=current(),ice=s=>String(s).replace(/\\/g,'\\\\').replace(/\n/g,'\\n').replace(/,/g,'\\,').replace(/;/g,'\\;');const lines=['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//ITCILO//Bangladesh Workshops 2026//EN','CALSCALE:GREGORIAN','BEGIN:VTIMEZONE','TZID:Asia/Dhaka','BEGIN:STANDARD','DTSTART:19700101T000000','TZOFFSETFROM:+0600','TZOFFSETTO:+0600','TZNAME:+06','END:STANDARD','END:VTIMEZONE'];for(const s of sessions(w)){const times=s.time.match(/\d{2}:\d{2}/g);if(!times||times.length<2)continue;const date=s.day.date.replaceAll('-','');lines.push('BEGIN:VEVENT',`UID:${s.id}@bangladesh-itcilo-2026`,`DTSTAMP:${new Date().toISOString().replace(/[-:]/g,'').replace(/\.\d{3}/,'')}`,`DTSTART;TZID=Asia/Dhaka:${date}T${times[0].replace(':','')}00`,`DTEND;TZID=Asia/Dhaka:${date}T${times[1].replace(':','')}00`,`SUMMARY:${ice(s.title)}`,`DESCRIPTION:${ice(w.title+'\n'+s.topics.join('\n'))}`,'LOCATION:Dhaka\, Bangladesh (exact venue to be confirmed)','END:VEVENT');}lines.push('END:VCALENDAR');const folded=lines.flatMap(l=>{const segments=[];let rest=l;while(rest.length>70){segments.push(rest.slice(0,70));rest=' '+rest.slice(70);}segments.push(rest);return segments;});downloadBytes(w.code+'_Sessions.ics',folded.join('\r\n')+'\r\n','text/calendar;charset=utf-8');}
  function paintTimer(){const left=timeLeft();if(timer.running&&left<=0){timer.running=false;timer.remaining=0;toast('Discussion time is up.');}$$('[data-timer-display]').forEach(el=>{el.textContent=clock(left);el.classList.toggle('timer-done',left===0);});$$('[data-timer="toggle"]').forEach(el=>el.textContent=timer.running?'Pause':'Start');$$('[data-timer-caption]').forEach(el=>el.textContent=left===0?'Time is up. Continue when the group is ready.':'The timer is a discussion prompt. It never blocks the game.');}
  function projectTimer(){timer.full=true;const panel=document.createElement('section');panel.id='timer-projection';panel.className='timer-full';panel.setAttribute('aria-label','Projected discussion timer');panel.innerHTML=`<div class="eyebrow" style="color:white">Bangladesh · Social dialogue workshops</div><h2>Time to discuss</h2><div class="timer-display" data-timer-display role="timer">${clock(timeLeft())}</div><div class="actions"><button class="button" data-timer="toggle">${timer.running?'Pause':'Start'}</button><button class="button" data-timer="add">+30 seconds</button><button class="button" data-timer="close">Return to facilitator view</button></div><p class="muted" style="margin-top:25px">Press Escape to return.</p>`;document.body.append(panel);panel.querySelector('button').focus();}
  function closeTimer(){$('#timer-projection')?.remove();timer.full=false;}
  function resultCode(code){const c=code.trim().toUpperCase();if(!/^[0-9A-Z]{5}D$/.test(c))return null;const n=parseInt(c.slice(0,2),36),t=parseInt(c.slice(2,4),36),checksum=parseInt(c[4],36);return n<=240&&checksum===(n*7+t*11+13)%36?{score:n,seconds:t*5,code:c}:null;}

  document.addEventListener('click',event=>{
    const t=event.target.closest('button,a');if(!t)return;
    if(t.hasAttribute('data-close-dialog')){$('#document-viewer').close();return;}
    if(t.dataset.preview){const a=D.activities.find(a=>a.id===t.dataset.preview);if(a)previewDocument(a.title,a.html,`<div class="actions" style="margin:0 0 22px">${dl(a.file,'Download original Word document')}</div>`);}
    if(t.dataset.script&&unlocked){const r=unlocked.find(r=>r.file===t.dataset.script);if(r)previewDocument(r.name.replace(/_/g,' ').replace('.docx',''),r.html);}
    if(t.dataset.unlockFile)protectedDownload(t.dataset.unlockFile,t);
    if(t.hasAttribute('data-lock')){key=null;unlocked=null;authTime=0;closeTimer();$('#document-viewer').close();$('#document-body').innerHTML='';render();toast('Facilitator view locked.');}
    if(t.hasAttribute('data-calendar'))calendar();
    if(t.hasAttribute('data-print'))window.print();
    if(t.hasAttribute('data-export-notes'))exportNotebook();
    if(t.hasAttribute('data-backup-notes'))downloadBytes('Bangladesh_2026_Notebooks_Backup.json',JSON.stringify({format:'bangladesh-notebooks-v1',notes},null,2),'application/json');
    if(t.hasAttribute('data-clear-notes')&&confirm('Clear this workshop’s saved notebook on this device? Export a copy first if you need it.')){notes[selected]={};write('notes',notes);render();toast('This workshop’s notebook was cleared.');}
    if(t.hasAttribute('data-clear-filters'))go('activities',{w:selected});
    if(t.dataset.timer){const action=t.dataset.timer;if(action==='toggle'){if(timer.running){timer.remaining=timeLeft();timer.running=false;}else if(timer.remaining>0){timer.deadline=Date.now()+timer.remaining*1000;timer.running=true;}}if(action==='add'){if(timer.running)timer.deadline+=30000;else timer.remaining+=30;}if(action==='reset'){timer.running=false;timer.remaining=Math.max(1,Math.min(90,Number($('#timer-minutes')?.value)||5))*60;}if(action==='full')projectTimer();if(action==='close')closeTimer();paintTimer();}
    if(t.dataset.removeResult&&unlocked){board=board.filter(r=>r.id!==t.dataset.removeResult);write('board',board);$('#board-results').innerHTML=boardTable();}
    if(t.hasAttribute('data-clear-board')&&unlocked&&confirm('Clear the entered game results for this workshop on this device?')){board=board.filter(r=>r.workshop!==selected);write('board',board);$('#board-results').innerHTML=boardTable();}
    if(t.hasAttribute('data-export-board')&&unlocked){const rows=board.filter(r=>r.workshop===selected).sort((a,b)=>b.score-a.score||a.seconds-b.seconds);downloadBytes(current().code+'_Game_Results.csv','Rank,Team,Points,Time_seconds,Result_code\r\n'+rows.map((r,i)=>[i+1,'"'+String(r.team).replace(/"/g,'""').replace(/^[=+@-]/,"'")+'"',r.score,r.seconds,r.code].join(',')).join('\r\n'),'text/csv;charset=utf-8');}
  });
  document.addEventListener('submit',event=>{
    if(event.target.id==='facilitator-login'){unlock(event);return;}
    if(event.target.id==='result-form'){event.preventDefault();if(!unlocked)return;const parsed=resultCode($('#result-code').value),team=$('#result-team').value.trim();if(!parsed||!team){$('#result-error').textContent='Check the team alias and six-character result code.';return;}$('#result-error').textContent='';board.push({...parsed,team,workshop:selected,id:crypto.randomUUID()});write('board',board);$('#board-results').innerHTML=boardTable();event.target.reset();$('#result-team').focus();toast('Team result added.');}
  });
  document.addEventListener('input',event=>{
    const t=event.target;
    if(t.dataset.note){if(!notes[selected])notes[selected]={};notes[selected][t.dataset.note]=t.value;const ok=write('notes',notes);$('#save-state').textContent=ok?'Saved on this device.':'Could not save. Export your notes now.';}
    if(t.id==='activity-search'){filterQuery=t.value;const n=Number($('#activity-session').value);$('#activity-results').innerHTML=resourceCards(current(),n,filterQuery);}
  });
  document.addEventListener('change',async event=>{
    const t=event.target;
    if(t.dataset.complete){completed=completed.filter(id=>id!==t.dataset.complete);if(t.checked)completed.push(t.dataset.complete);write('completed',completed);render();}
    if(t.id==='activity-session')go('activities',{w:selected,...(Number(t.value)?{session:t.value}:{})});
    if(t.id==='timer-minutes'&&!timer.running){timer.remaining=Math.max(1,Math.min(90,Number(t.value)||5))*60;paintTimer();}
    if(t.id==='restore-notes'&&t.files?.[0]){try{if(t.files[0].size>2000000)throw new Error('That file is too large for a notebook backup.');const backup=JSON.parse(await t.files[0].text());if(backup.format!=='bangladesh-notebooks-v1'||!backup.notes||typeof backup.notes!=='object')throw new Error('Choose a Bangladesh notebook backup JSON file.');const safe={};for(const w of D.workshops){safe[w.id]={};for(const [id] of [...COMMON_FIELDS,...(w.id==='institutions'?INSTITUTION_FIELDS:SECRETARIAT_FIELDS)]){const v=backup.notes[w.id]?.[id];if(typeof v==='string')safe[w.id][id]=v.slice(0,30000);}}if(!confirm('Replace the two notebooks on this device with this backup?'))return;notes=safe;write('notes',notes);render();toast('Both notebooks restored.');}catch(e){toast(e.message);}}
  });
  document.addEventListener('keydown',e=>{if(e.key==='Escape'&&timer.full)closeTimer();});
  $('#document-viewer').addEventListener('click',e=>{if(e.target===$('#document-viewer')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close();}});
  window.addEventListener('hashchange',()=>{closeTimer();$('#document-viewer').close();render();window.scrollTo(0,0);main.focus({preventScroll:true});});
  setInterval(()=>{paintTimer();if(unlocked&&Date.now()-authTime>=90*60*1000){key=null;unlocked=null;authTime=0;closeTimer();$('#document-viewer').close();$('#document-body').innerHTML='';if(route==='facilitator')render();toast('Facilitator session ended. Sign in to unlock it again.');}},500);render();
})();
